const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries for Bryce Canyon and Las Vegas
  const brycePoint = ee.Geometry.Point([-112.167, 37.628]);
  const vegasPoint = ee.Geometry.Point([-115.1398, 36.1699]);

  // Buffer by 5km for area analysis
  const bryceArea = brycePoint.buffer(5000); // 5km radius
  const vegasArea = vegasPoint.buffer(5000); // 5km radius

  // 2. Define date range for 2024
  const startDate = '2024-01-01';
  const endDate = '2024-12-31';

  // 3. Get VIIRS nighttime light monthly composites for 2024
  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/001/VNP46A4')
    .filterDate(startDate, endDate)
    .select('DNB_BRDF-Corrected_NTL'); // Nighttime light band

  // Check collection size
  const collectionSize = viirsCollection.size().getInfo();
  console.log(`2024 VIIRS Monthly Images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No nighttime light data found for 2024.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Compute mean image for the year
  const meanImage = viirsCollection.mean();

  // 5. Extract mean nighttime light values for both locations
  const bryceStats = meanImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: bryceArea,
    scale: 1000,
    maxPixels: 1e9,
    bestEffort: true
  });

  const vegasStats = meanImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: vegasArea,
    scale: 1000,
    maxPixels: 1e9,
    bestEffort: true
  });

  // Get pixel counts to check for valid data
  const bryceCount = meanImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: bryceArea,
    scale: 1000,
    maxPixels: 1e9,
    bestEffort: true
  }).get('DNB_BRDF-Corrected_NTL');

  const vegasCount = meanImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: vegasArea,
    scale: 1000,
    maxPixels: 1e9,
    bestEffort: true
  }).get('DNB_BRDF-Corrected_NTL');

  // Get values
  const bryceValue = bryceStats.get('DNB_BRDF-Corrected_NTL');
  const vegasValue = vegasStats.get('DNB_BRDF-Corrected_NTL');

  // Evaluate
  const bryceVal = bryceValue.getInfo();
  const vegasVal = vegasValue.getInfo();
  const brycePixels = bryceCount.getInfo();
  const vegasPixels = vegasCount.getInfo();

  console.log(`Bryce Canyon - Mean NTL: ${bryceVal?.toFixed(2) || 'null'}, Valid Pixels: ${brycePixels}`);
  console.log(`Las Vegas - Mean NTL: ${vegasVal?.toFixed(2) || 'null'}, Valid Pixels: ${vegasPixels}`);

  // Check for no valid pixels
  if (brycePixels === 0 || vegasPixels === 0) {
    console.log("No valid pixels in one or both locations.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (bryceVal === null || vegasVal === null || 
      isNaN(bryceVal) || isNaN(vegasVal) ||
      bryceVal < 0 || vegasVal < 0 || // Negative values unlikely for NTL
      bryceVal > 1000 || vegasVal > 1000) { // Unreasonably high
    console.log("Invalid or unreasonable NTL values detected.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare values (nighttime light intensity)
  const bryceLower = bryceVal < vegasVal;

  console.log(`Comparison: Bryce (${bryceVal?.toFixed(2)}) < Vegas (${vegasVal?.toFixed(2)})? ${bryceLower}`);

  // Output final answer
  if (bryceLower) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
